style:
/* 研路 —— 藏青页眉与矩形标牌标题，报考信息成表 */

.tw-yanlu.layout-band.resume-paper .paper-header {
  margin: -15mm -15mm 7.5mm;
  padding: 10mm 15mm 7mm;
  align-items: flex-start;
  gap: 7mm;
  background: var(--paper-accent);
  border: none;
  color: #fff;
  print-color-adjust: exact;
}

.tw-yanlu.layout-band.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-yanlu.layout-band.resume-paper .paper-photo {
  order: 3;
  width: 24mm;
  height: 32mm;
  border: 0.5mm solid rgba(255, 255, 255, 0.55);
  border-radius: 0;
  box-shadow: none;
  print-color-adjust: exact;
}

.tw-yanlu.layout-band.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-yanlu.layout-band.resume-paper .paper-name {
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.2);
  letter-spacing: 0.1em;
}

.tw-yanlu.layout-band.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: rgba(255, 255, 255, 0.78);
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-yanlu.layout-band.resume-paper .paper-role {
  margin-top: 2mm;
  color: rgba(255, 255, 255, 0.92);
  font-size: calc(var(--paper-base-size) * 1.02);
  font-weight: 500;
  letter-spacing: 0.04em;
}

.tw-yanlu.layout-band.resume-paper .paper-contacts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 8mm;
  margin-top: 4mm;
  color: rgba(255, 255, 255, 0.9);
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-yanlu.layout-band.resume-paper .paper-contact {
  display: flex;
  gap: 1.6mm;
}

.tw-yanlu.layout-band.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-yanlu.layout-band.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: rgba(255, 255, 255, 0.62);
}

/* 模块标题：藏青标牌，右端切一刀 */
.tw-yanlu.layout-band.resume-paper .paper-style-block .paper-section__title {
  display: inline-flex;
  align-items: center;
  gap: 2mm;
  margin-bottom: 3.6mm;
  padding: 1.2mm 5mm 1.2mm 3.2mm;
  background: var(--paper-accent);
  border-radius: 0;
  clip-path: polygon(0 0, 100% 0, calc(100% - 2.6mm) 100%, 0 100%);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.02);
  letter-spacing: 0.1em;
  print-color-adjust: exact;
}

.tw-yanlu.layout-band.resume-paper .paper-section__body {
  color: #26313f;
}

.tw-yanlu.layout-band.resume-paper .paper-item-title {
  color: #17222f;
}

.tw-yanlu.layout-band.resume-paper .paper-item-period {
  color: #6d7b8c;
}

.tw-yanlu.layout-band.resume-paper .paper-item-sub {
  color: #46556a;
}

/* 报考信息排成两列表格 */
.tw-yanlu.layout-band.resume-paper .paper-facts {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  border-top: 0.25mm solid #ccd5e1;
  border-left: 0.25mm solid #ccd5e1;
}

.tw-yanlu.layout-band.resume-paper .paper-facts > div {
  flex-direction: row;
  align-items: baseline;
  gap: 3mm;
  padding: 1.6mm 2.6mm;
  border-right: 0.25mm solid #ccd5e1;
  border-bottom: 0.25mm solid #ccd5e1;
}

.tw-yanlu.layout-band.resume-paper .paper-facts span {
  flex: 0 0 auto;
  color: #6d7b8c;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-yanlu.layout-band.resume-paper .paper-facts strong {
  font-weight: 600;
}

.tw-yanlu.layout-band.resume-paper .paper-rich ul,
.tw-yanlu.layout-band.resume-paper .paper-rich ol {
  margin-top: 1mm;
  padding-left: 1.1em;
}

.tw-yanlu.layout-band.resume-paper .paper-rich li::marker {
  color: var(--paper-accent);
}

.tw-yanlu.layout-band.resume-paper .paper-note__tag {
  color: var(--paper-accent);
  font-weight: 600;
}

.tw-yanlu.layout-band.resume-paper .paper-footer {
  border-top: 0.2mm solid #e2e7ee;
  color: #9ba5b3;
}
